BY = {e['uid']: e for e in W}
lab = {r['customer_id']: r for r in csv.DictReader(open('/app/dev/labels_dev.csv'))}
cus = {r['customer_id']: r for r in csv.DictReader(open('/app/dev/customers_dev.csv'))}

def strip_acc(s):
    s = unicodedata.normalize('NFD', s)
    return ''.join(c for c in s if not unicodedata.combining(c))

def toks(s):
    return [t.lower() for t in re.split(r'[^0-9A-Za-z؀-ۿЀ-ӿ]+', strip_acc(s)) if t]

PARTICLES = {'al','el','bin','ibn','ben','b','abu','abd','bint','du','de','van','von','der','the','and'}

sub = collections.Counter()
for cid, l in lab.items():
    if l['expected_decision'] != 'MATCH': continue
    e = BY[l['expected_uid']]
    if e['type'] != 'individual': continue
    ct = [t for t in toks(cus[cid]['full_name']) if t not in PARTICLES and len(t) > 1]
    names = [e['primary_name']] + [a['name'] for a in e['aliases']]
    et = []
    for n in names:
        et += [t for t in toks(n) if t not in PARTICLES and len(t) > 1]
    et = list(dict.fromkeys(et))
    used = set()
    for c in ct:
        if c in et:
            sub[(c, c)] += 1; used.add(c); continue
        # best fuzzy partner not already consumed
        best, bs = None, 0.0
        for x in et:
            if x in used: continue
            s = difflib.SequenceMatcher(None, c, x).ratio()
            if c[0] == x[0]: s += 0.12
            if s > bs: best, bs = x, s
        if best and bs > 0.45:
            sub[(c, best)] += 1; used.add(best)
        else:
            sub[(c, '<<NONE>>')] += 1

diff = [(v, a, b) for (a, b), v in sub.items() if a != b and b != '<<NONE>>']
diff.sort(reverse=True)
print('distinct variant->canon pairs:', len(diff))
print('unaligned:', sum(v for (a, b), v in sub.items() if b == '<<NONE>>'))
for v, a, b in diff[:80]:
    print(f'{v:3d}  {a:22s} -> {b}')
