import csv, subprocess, sys, collections, time

def run(cust, out):
    t0 = time.time()
    r = subprocess.run([sys.executable, '/app/screen.py', '--watchlist', '/app/watchlist.json',
                        '--customers', cust, '--out', out], capture_output=True, text=True)
    if r.returncode:
        print(r.stdout, r.stderr); sys.exit(1)
    return time.time() - t0

def score(labels, out, show=True):
    lab = {r['customer_id']: r for r in csv.DictReader(open(labels))}
    got = {r['customer_id']: r for r in csv.DictReader(open(out))}
    per = collections.defaultdict(lambda: [0, 0, 0, 0])  # n, correct_decision, tp, uid_ok
    tp = fp = fn = uid_bad = 0
    errs = collections.defaultdict(list)
    for cid, l in lab.items():
        g = got.get(cid, {'decision': 'NO_MATCH', 'matched_uid': ''})
        cls = l['class']
        exp_m = l['expected_decision'] == 'MATCH'
        got_m = g['decision'] == 'MATCH'
        per[cls][0] += 1
        if exp_m and got_m:
            tp += 1; per[cls][2] += 1
            if g['matched_uid'] == l['expected_uid']:
                per[cls][3] += 1
            else:
                uid_bad += 1
                errs['UID:' + cls].append((cid, l['expected_uid'], g['matched_uid']))
        elif exp_m and not got_m:
            fn += 1; errs['FN:' + cls].append((cid, l['expected_uid'], ''))
        elif not exp_m and got_m:
            fp += 1; errs['FP:' + cls].append((cid, '', g['matched_uid']))
        if exp_m == got_m:
            per[cls][1] += 1
    rec = tp / (tp + fn) if tp + fn else 1.0
    prec = tp / (tp + fp) if tp + fp else 1.0
    uidacc = (tp - uid_bad) / tp if tp else 1.0
    if show:
        print(f'recall {rec:.4f}  precision {prec:.4f}  uid_acc {uidacc:.4f}   tp={tp} fp={fp} fn={fn} uid_bad={uid_bad}')
        print('per class:')
        for cls in sorted(per):
            n, ok, ctp, cuid = per[cls]
            if cls.startswith('T'):
                exp = sum(1 for l in lab.values() if l['class'] == cls and l['expected_decision'] == 'MATCH')
                print(f'  {cls:28s} n={n:4d} recall={ctp/exp if exp else 1:.3f}  uid={cuid/ctp if ctp else 1:.3f}')
            else:
                bad = n - ok
                print(f'  {cls:28s} n={n:4d} FPrate={bad/n:.3f}')
    return rec, prec, uidacc, errs

if __name__ == '__main__':
    dt = run('/app/dev/customers_dev.csv', '/tmp/dev_out.csv')
    print(f'runtime {dt:.1f}s')
    rec, prec, uidacc, errs = score('/app/dev/labels_dev.csv', '/tmp/dev_out.csv')
    if len(sys.argv) > 1:
        cus = {r['customer_id']: r for r in csv.DictReader(open('/app/dev/customers_dev.csv'))}
        import json
        W = {e['uid']: e for e in json.load(open('/app/watchlist.json'))}
        for k in sorted(errs):
            if sys.argv[1] not in k and sys.argv[1] != 'all':
                continue
            print('===', k, len(errs[k]))
            for cid, exp, gotu in errs[k][:int(sys.argv[2]) if len(sys.argv) > 2 else 8]:
                c = cus[cid]
                print(f'   {c["full_name"]!r} dob={c["dob"]} type={c["type"]} id={c["id_type"]}:{c["id_number"]}')
                if exp:
                    e = W[exp]
                    print(f'      EXPECT {exp} {e["primary_name"]!r} dob={e["dob"]} aliases={[a["name"] for a in e["aliases"]]}')
                if gotu:
                    e = W[gotu]
                    print(f'      GOT    {gotu} {e["primary_name"]!r} dob={e["dob"]}')

